// Java: 长度前缀方案解决粘包拆包
public class LengthPrefixDecoder {
    private static final int HEADER_SIZE = 4;

    // 编码: 在消息前添加4字节长度
    public static byte[] encode(byte[] data) {
        byte[] result = new byte[HEADER_SIZE + data.length];
        // 写入长度(大端序)
        result[0] = (byte) (data.length >> 24);
        result[1] = (byte) (data.length >> 16);
        result[2] = (byte) (data.length >> 8);
        result[3] = (byte) data.length;
        System.arraycopy(data, 0, result, HEADER_SIZE, data.length);
        return result;
    }

    // 解码: 先读长度，再读对应字节数
    public static List<byte[]> decode(byte[] buffer) {
        List<byte[]> messages = new ArrayList<>();
        int offset = 0;
        while (offset + HEADER_SIZE <= buffer.length) {
            // 读取长度
            int length = ((buffer[offset] & 0xFF) << 24)
                       | ((buffer[offset + 1] & 0xFF) << 16)
                       | ((buffer[offset + 2] & 0xFF) << 8)
                       | (buffer[offset + 3] & 0xFF);
            // 检查数据是否完整
            if (offset + HEADER_SIZE + length > buffer.length) {
                break;  // 数据不完整，等待更多数据
            }
            // 提取消息
            byte[] message = new byte[length];
            System.arraycopy(buffer, offset + HEADER_SIZE, message, 0, length);
            messages.add(message);
            offset += HEADER_SIZE + length;
        }
        return messages;
    }
}

// Go: 长度前缀方案
type LengthPrefixCodec struct{}

func (c *LengthPrefixCodec) Encode(data []byte) []byte {
    length := len(data)
    result := make([]byte, 4+length)
    binary.BigEndian.PutUint32(result[:4], uint32(length))
    copy(result[4:], data)
    return result
}

func (c *LengthPrefixCodec) Decode(reader io.Reader) ([]byte, error) {
    // 先读4字节长度
    header := make([]byte, 4)
    if _, err := io.ReadFull(reader, header); err != nil {
        return nil, err
    }
    length := binary.BigEndian.Uint32(header)
    // 再读length字节数据
    data := make([]byte, length)
    if _, err := io.ReadFull(reader, data); err != nil {
        return nil, err
    }
    return data, nil
}
